package com.lianxibu.site.repository.sources;
import com.lianxibu.site.domain.jobs.SourceContractFacts;import com.lianxibu.site.domain.protocol.CanonicalJson;import com.lianxibu.site.domain.protocol.WireValues;import com.lianxibu.site.service.sources.ManualSourceAdmission;
import java.time.*;import java.time.temporal.ChronoUnit;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.*;import org.springframework.transaction.support.*;
/** Complete current-source/manual-proof/all-authorized-node facts in one owned read-only RR snapshot. */
public final class JdbcSourceContractFacts implements SourceContractFacts.Api {
 private final JdbcTemplate jdbc;private final TransactionTemplate reads;private final JdbcSourceContractSnapshots snapshots;private final Clock clock;
 private record Source(String id,long revision,long version,Instant valid,String category,String legacy,String draft,String effective){}
 private record Node(String id,long revision,Set<String> sources,Set<String> permissions){}
 public JdbcSourceContractFacts(DataSource source,PlatformTransactionManager manager,Clock clock){jdbc=new JdbcTemplate(Objects.requireNonNull(source));snapshots=new JdbcSourceContractSnapshots(source);this.clock=Objects.requireNonNull(clock);reads=new TransactionTemplate(Objects.requireNonNull(manager));reads.setReadOnly(true);reads.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);reads.setTimeout(10);}
 @Override public SourceContractFacts.Evidence read(String sourceId){
  WireValues.id(sourceId,true);if(TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("source facts require an owned outside read snapshot");
  try{return reads.execute(ignored->capture(sourceId));}catch(RuntimeException unavailable){return null;}
 }
 private SourceContractFacts.Evidence capture(String id){
  Instant at=clock.instant().truncatedTo(ChronoUnit.MICROS);var rows=jdbc.query("SELECT id,revision,config_revision,config_valid_until,category,CASE WHEN OCTET_LENGTH(config_json) BETWEEN 1 AND 65536 THEN config_json ELSE NULL END,CASE WHEN OCTET_LENGTH(draft_config_json) BETWEEN 1 AND 65536 THEN draft_config_json ELSE NULL END,CASE WHEN OCTET_LENGTH(effective_config_json) BETWEEN 1 AND 65536 THEN effective_config_json ELSE NULL END FROM sources WHERE id=? AND activation_stage='production'",(r,n)->new Source(r.getString(1),r.getLong(2),r.getLong(3),r.getTimestamp(4,utc())==null?null:r.getTimestamp(4,utc()).toInstant(),r.getString(5),r.getString(6),r.getString(7),r.getString(8)),id);
  if(rows.size()!=1)return null;var source=rows.getFirst();if(source.revision()<1||source.revision()>CanonicalJson.MAX_SAFE_INTEGER||source.version()<1||source.version()>CanonicalJson.MAX_SAFE_INTEGER||source.valid()==null||!source.valid().isAfter(at)||source.category()==null||source.legacy()==null||source.draft()==null||source.effective()==null||!CanonicalJson.parse(source.draft()).equals(CanonicalJson.parse(source.effective())))return null;
  Instant reviewed=manual(source,at);if(reviewed==null)return null;
  var nodes=jdbc.query("SELECT id,config_revision,CASE WHEN OCTET_LENGTH(allowed_source_ids) BETWEEN 1 AND 65536 THEN allowed_source_ids ELSE NULL END,CASE WHEN OCTET_LENGTH(permissions_json) BETWEEN 1 AND 2048 THEN permissions_json ELSE NULL END FROM collector_nodes WHERE enabled=1 ORDER BY id LIMIT 129",(r,n)->{String node=WireValues.id(r.getString(1),false);long version=r.getLong(2);if(version<1||version>CanonicalJson.MAX_SAFE_INTEGER)throw invalid();return new Node(node,version,array(r.getString(3),1000,true),array(r.getString(4),8,false));});if(nodes.size()>128)return null;
  long total=0,events=0;int count=0;Instant observed=at,received=at;StringBuilder epochs=new StringBuilder();
  for(var node:nodes){if(!node.sources().contains(id))continue;if(!node.permissions().contains("heartbeat:write"))return null;var receipt=snapshots.latest(node.id(),id);if(receipt==null||receipt.nodeRevision()!=node.revision())return null;var value=receipt.input().snapshot();if(value.configVersion()!=source.version()||value.observedAt().isAfter(at)||receipt.receivedAt().isAfter(at)||Duration.between(value.observedAt(),at).getSeconds()>120||Duration.between(receipt.receivedAt(),at).getSeconds()>120)return null;
   total=Math.addExact(total,value.totalFailures());for(var event:value.events())if(event.occurredAt().isAfter(at.minusSeconds(600)))events=Math.addExact(events,1);count++;if(value.observedAt().isBefore(observed))observed=value.observedAt();if(receipt.receivedAt().isBefore(received))received=receipt.receivedAt();epochs.append(node.id()).append('\n').append(node.revision()).append('\n').append(value.epoch()).append('\n');
  }
  if(count==0)return null;return new SourceContractFacts.Evidence(id,source.version(),sha(epochs.toString()),total,events,count,observed,received,at,reviewed);
 }
 private Instant manual(Source source,Instant at){
  var values=jdbc.query("SELECT id,principal,actor_id,request_key,request_key_raw,key_hash,request_hash,business_hash,created_at,CASE WHEN OCTET_LENGTH(ack_json) BETWEEN 1 AND 65536 THEN ack_json ELSE NULL END,CASE WHEN OCTET_LENGTH(result_ref_json) BETWEEN 1 AND 2048 THEN result_ref_json ELSE NULL END,status_code,original_status,current_status,expires_at,response_json FROM request_receipts WHERE source_id=? AND scope='manual-source-admission-v1' AND receipt_kind='admin_action' AND operation='manual_approve' AND revision=? LIMIT 2",(r,n)->{
   if(r.getString(10)==null||r.getString(11)==null||r.getInt(12)!=200||!"applied".equals(r.getString(13))||!"applied".equals(r.getString(14))||r.getObject(15)!=null||r.getObject(16)!=null)throw invalid();
   var m=ManualSourceAdmission.Manifest.parse(r.getString(10).getBytes(StandardCharsets.UTF_8));String actor=WireValues.id(r.getString(3),false),action=m.text("action_key");Instant created=r.getTimestamp(9,utc()).toInstant(),reviewed=Instant.parse(m.text("reviewed_at")),expires=Instant.parse(m.text("expires_at"));
   var keys=Set.of("source_id","revision","activation_stage");var result=WireValues.object(CanonicalJson.parse(r.getString(11)),keys,keys);
   if(!source.id().equals(m.text("source_id"))||!actor.equals(m.text("reviewer_id"))||!actor.equals(r.getString(2))||!action.equals(r.getString(4))||!action.equals(r.getString(5))||!Arrays.equals(r.getBytes(6),HexFormat.of().parseHex(sha(action)))||!Arrays.equals(r.getBytes(7),HexFormat.of().parseHex(sha("approve\n"+m.canonical())))||!Arrays.equals(r.getBytes(7),r.getBytes(8))||m.number("expected_revision")+1!=source.revision()||m.number("config_version")!=source.version()||!m.text("config_sha256").equals(sha(source.draft()))||!m.text("legacy_config_sha256").equals(sha(source.legacy()))||!m.text("parser_version").equals(WireValues.text(CanonicalJson.parse(source.effective()).get("parser_version")))||created.isAfter(at)||reviewed.isAfter(created)||!expires.equals(source.valid())||!expires.isAfter(at)||m.number("valid_samples")<("news_tech".equals(source.category())?3:1)||!source.id().equals(WireValues.id(result.get("source_id"),true))||WireValues.nonnegativeInteger(result.get("revision"))!=source.revision()||!"production".equals(WireValues.text(result.get("activation_stage")))||jdbc.queryForObject("SELECT COUNT(*) FROM users WHERE id=?",Integer.class,actor)!=1)throw invalid();
   var manifest=CanonicalJson.parse(m.canonical());for(String check:List.of("tls_network","root_format","required_fields","stable_ids","time_fields","usage_scope","adapter_roundtrip"))if(!manifest.get("checks").get(check).booleanValue())throw invalid();return reviewed;
  },source.id(),source.revision());if(values.size()!=1)return null;return values.getFirst();
 }
 private static Set<String> array(String raw,int max,boolean source){if(raw==null)throw invalid();var value=CanonicalJson.parse(raw);if(!value.isArray()||value.size()>max)throw invalid();var values=new TreeSet<String>();var permissions=Set.of("config:read","run:claim","run:read","run:write","observation:write","heartbeat:write","probe:claim","probe:write");for(var item:value){String id=WireValues.id(item,source);if(!values.add(id)||!source&&!permissions.contains(id))throw invalid();}return Set.copyOf(values);}
 private static Calendar utc(){return Calendar.getInstance(TimeZone.getTimeZone("UTC"));}
 private static String sha(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException failure){throw invalid();}}
 private static IllegalStateException invalid(){return new IllegalStateException("complete native source facts unavailable");}
}
